// Generated by vibes-espmatter – updates from the vibes-espmatter app: every few minutes the device asks
// whether its owner started an update of it there (/api/updates/self), installs it (esp_https_ota),
// reports how far it got and restarts. The app's address and the device's token come with the build
// and can be changed (/api/updates/server).
#include "espm_updates.h"
#include "espm_web.h"
#include "espm_config.h"

#include <cctype>
#include <cstdio>
#include <cstring>
#include <esp_crt_bundle.h>
#include <esp_http_client.h>
#include <esp_https_ota.h>
#include <esp_log.h>
#include <freertos/FreeRTOS.h>
#include <freertos/semphr.h>
#include <freertos/task.h>
#include <nvs.h>

static const char *TAG = "mesp_updates";

#define FIRST_CHECK_S 60
#define CHECK_EVERY_S 300

static char s_server[160] = MESP_UPDATES_URL;
static char s_token[128] = MESP_UPDATES_TOKEN;
static SemaphoreHandle_t s_mutex;

struct Lock {
    Lock() { xSemaphoreTake(s_mutex, portMAX_DELAY); }
    ~Lock() { xSemaphoreGive(s_mutex); }
};

static void settings_load()
{
    nvs_handle_t h;
    if (nvs_open("mesp_updates", NVS_READONLY, &h) != ESP_OK) return;
    size_t len = sizeof(s_server);
    nvs_get_str(h, "server", s_server, &len);
    len = sizeof(s_token);
    nvs_get_str(h, "token", s_token, &len);
    nvs_close(h);
}

static void settings_save()
{
    nvs_handle_t h;
    if (nvs_open("mesp_updates", NVS_READWRITE, &h) != ESP_OK) return;
    nvs_set_str(h, "server", s_server);
    nvs_set_str(h, "token", s_token);
    nvs_commit(h);
    nvs_close(h);
}

const char *mesp_updates_server()
{
    return s_server;
}

/** Client for `path` of the app, with the token; null without a server. */
static esp_http_client_handle_t client_for(const char *path, esp_http_client_method_t method)
{
    char url[400];
    char auth[160];
    {
        Lock lock;
        if (!s_server[0]) return nullptr;
        snprintf(url, sizeof(url), "%s%s", s_server, path);
        snprintf(auth, sizeof(auth), "Bearer %s", s_token);
    }
    esp_http_client_config_t config = {};
    config.url = url;
    config.method = method;
    config.crt_bundle_attach = esp_crt_bundle_attach;
    config.timeout_ms = 15000;
    esp_http_client_handle_t client = esp_http_client_init(&config);
    if (client) esp_http_client_set_header(client, "Authorization", auth);
    return client;
}

int mesp_updates_get(const char *path, char *body, size_t len)
{
    body[0] = '\0';
    esp_http_client_handle_t client = client_for(path, HTTP_METHOD_GET);
    if (!client) return -1;
    int status = -1;
    if (esp_http_client_open(client, 0) == ESP_OK && esp_http_client_fetch_headers(client) >= 0) {
        status = esp_http_client_get_status_code(client);
        int got = 0, n;
        while (got < (int)len - 1 && (n = esp_http_client_read(client, body + got, len - 1 - got)) > 0) got += n;
        body[got] = '\0';
    }
    esp_http_client_cleanup(client);
    return status;
}

int mesp_updates_post(const char *path, const char *form)
{
    esp_http_client_handle_t client = client_for(path, HTTP_METHOD_POST);
    if (!client) return -1;
    esp_http_client_set_header(client, "Content-Type", "application/x-www-form-urlencoded");
    esp_http_client_set_post_field(client, form, strlen(form));
    int status = esp_http_client_perform(client) == ESP_OK ? esp_http_client_get_status_code(client) : -1;
    esp_http_client_cleanup(client);
    return status;
}

void mesp_updates_report(const char *key, const char *id, unsigned long version, const char *state,
                         const char *message)
{
    char form[220];
    int n = snprintf(form, sizeof(form), "%s=%s&version=%lu&state=%s&message=", key, id, version, state);
    for (const char *c = message; *c && n < (int)sizeof(form) - 4; c++)
        n += isalnum((unsigned char)*c) ? snprintf(form + n, 2, "%c", *c)
                                        : snprintf(form + n, 4, "%%%02X", (unsigned char)*c);
    mesp_updates_post("/api/updates/status", form);
}

static void report(unsigned long version, const char *state, const char *message = "")
{
    mesp_updates_report("role", MESP_ROLE, version, state, message);
}

/** Install the update the owner started in the app, if there is one. Restarts after it. */
static void check()
{
    char path[96];
    char body[512];
    snprintf(path, sizeof(path), "/api/updates/self?role=%s&version=%lu", MESP_ROLE,
             (unsigned long)MESP_BUILD_VERSION);
    if (mesp_updates_get(path, body, sizeof(body)) != 200) return;
    // version, version string, image URL
    char *version_str = strchr(body, '\n');
    char *url = version_str ? strchr(version_str + 1, '\n') : nullptr;
    if (!url) return;
    *url++ = '\0';
    url[strcspn(url, "\r\n")] = '\0';
    unsigned long version = strtoul(body, nullptr, 10);
    ESP_LOGI(TAG, "Installing version %s", version_str + 1);
    report(version, "downloading");

    esp_http_client_config_t http = {};
    http.url = url;
    http.crt_bundle_attach = esp_crt_bundle_attach;
    http.timeout_ms = 30000;
    http.keep_alive_enable = true;
    esp_https_ota_config_t ota = {};
    ota.http_config = &http;
    esp_err_t err = esp_https_ota(&ota);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "Update failed: %s", esp_err_to_name(err));
        report(version, "failed", esp_err_to_name(err));
        return;
    }
    // The app marks it done once the new firmware asks with its version.
    report(version, "installing");
    ESP_LOGI(TAG, "Installed, restarting");
    esp_restart();
}

static void updates_task(void *)
{
    vTaskDelay(pdMS_TO_TICKS(FIRST_CHECK_S * 1000));
    while (true) {
        check();
        vTaskDelay(pdMS_TO_TICKS(CHECK_EVERY_S * 1000));
    }
}

static esp_err_t server_get_handler(httpd_req_t *req)
{
    if (!mesp_web_authorized(req)) return ESP_OK;
    Json j;
    Lock lock;
    j.obj().key("server").str(s_server).key("hasToken").boolean(s_token[0] != '\0').end_obj();
    return mesp_web_send_json(req, j.out());
}

static esp_err_t server_post_handler(httpd_req_t *req)
{
    if (!mesp_web_authorized(req)) return ESP_OK;
    std::string body, server, token;
    if (!mesp_web_read_body(req, body)) return ESP_OK;
    bool has_server = mesp_web_param(body, "server", server);
    while (!server.empty() && server.back() == '/') server.pop_back();
    if (server.size() >= sizeof(s_server) ||
        (!server.empty() && server.rfind("http://", 0) != 0 && server.rfind("https://", 0) != 0))
        return mesp_web_send_error(req, "400 Bad Request", "Server: an http(s):// URL");
    // No token: keep the one there is.
    bool has_token = mesp_web_param(body, "token", token);
    if (token.size() >= sizeof(s_token)) return mesp_web_send_error(req, "400 Bad Request", "Token too long");
    {
        Lock lock;
        if (has_server) strlcpy(s_server, server.c_str(), sizeof(s_server));
        if (has_token) strlcpy(s_token, token.c_str(), sizeof(s_token));
        settings_save();
    }
    return mesp_web_send_json(req, "{\"ok\":true}");
}

void mesp_updates_start()
{
    s_mutex = xSemaphoreCreateMutex();
    settings_load();
    mesp_web_add("/api/updates/server", HTTP_GET, server_get_handler);
    mesp_web_add("/api/updates/server", HTTP_POST, server_post_handler);
    xTaskCreate(updates_task, "mesp_updates", 6144, nullptr, 3, nullptr);
}
